mapper.select:
SELECT mpm.MEMBER_PT_NO ,mpm.MEMBER_NO ,mpm.CONT_NO ,cm.CONT_NM ,mpm.ORG_NO ,(CASE WHEN pm.BAL_PT IS NULL THEN 0 ELSE pm.BAL_PT END) AS BAL_PT ,mpm.ISU_PT ,mpm.ISU_CANCEL_PT ,mpm.USE_PT ,mpm.USE_CANCEL_PT ,mpm.EXP_PT ,mpm.REG_USER_ID ,mpm.REG_DT ,mpm.LAST_MOD_USER_ID ,mpm.LAST_MOD_DT FROM T_MEMBER_PT_MST mpm INNER JOIN T_CONT_MST cm ON cm.CONT_NO = mpm.CONT_NO LEFT OUTER JOIN (SELECT CONT_NO, SUM(BAL_PT) BAL_PT FROM T_PT_MST WHERE EXP_DT > CURRENT_TIMESTAMP(6) AND BAL_PT > 0
AND MEMBER_PT_NO = #{memberPtNo}
AND MEMBER_NO = #{memberNo}
AND CONT_NO = #{contNo}
GROUP BY CONT_NO ) AS pm ON pm.CONT_NO = mpm.CONT_NO WHERE 1 = 1
AND mpm.MEMBER_PT_NO = #{memberPtNo}
AND mpm.MEMBER_NO = #{memberNo}
AND mpm.CONT_NO = #{contNo}
AND mpm.ORG_NO = #{orgNo}

SELECT
     CASE WHEN #{trGbCd} = 'S001' THEN BAL_PT - #{trPt}
          WHEN #{trGbCd} = 'SC01' THEN BAL_PT + #{trPt}
          WHEN #{trGbCd} = 'U001' THEN BAL_PT + #{trPt}
          WHEN #{trGbCd} = 'UC01' THEN BAL_PT - #{trPt}
          WHEN #{trGbCd} = 'EX01' THEN BAL_PT + #{trPt}
     END AS BEF_BAL_PT
    ,CASE WHEN #{trGbCd} = 'S001' THEN BAL_PT
          WHEN #{trGbCd} = 'SC01' THEN BAL_PT
          WHEN #{trGbCd} = 'U001' THEN BAL_PT
          WHEN #{trGbCd} = 'UC01' THEN BAL_PT
          WHEN #{trGbCd} = 'EX01' THEN BAL_PT
     END AS AFR_BAL_PT
FROM T_MEMBER_PT_MST
WHERE MEMBER_PT_NO = #{memberPtNo}

mapper.update:
UPDATE T_MEMBER_PT_MST
  SET  BAL_PT = BAL_PT - #{usePt}
      ,USE_PT = USE_PT + #{usePt}
      ,LAST_MOD_USER_ID = #{lastModUserId, jdbcType=VARCHAR}
      ,LAST_MOD_DT= CURRENT_TIMESTAMP(6)
WHERE  MEMBER_PT_NO = #{memberPtNo}

UPDATE T_MEMBER_PT_MST
SET  BAL_PT = BAL_PT + #{useCancelPt}
    ,USE_CANCEL_PT = USE_CANCEL_PT + #{useCancelPt}
    ,LAST_MOD_USER_ID = #{lastModUserId, jdbcType=VARCHAR}
    ,LAST_MOD_DT= CURRENT_TIMESTAMP(6)
WHERE  MEMBER_PT_NO = #{memberPtNo}

UPDATE T_MEMBER_PT_MST
SET  BAL_PT = BAL_PT + #{isuPt}
    ,ISU_PT = ISU_PT + #{isuPt}
    ,LAST_MOD_USER_ID = #{lastModUserId, jdbcType=VARCHAR}
    ,LAST_MOD_DT= CURRENT_TIMESTAMP(6)
WHERE  MEMBER_PT_NO = #{memberPtNo}

UPDATE T_MEMBER_PT_MST
SET  BAL_PT = BAL_PT - #{isuCancelPt}
    ,ISU_CANCEL_PT = ISU_CANCEL_PT + #{isuCancelPt}
    ,LAST_MOD_USER_ID = #{lastModUserId, jdbcType=VARCHAR}
    ,LAST_MOD_DT= CURRENT_TIMESTAMP(6)
WHERE  MEMBER_PT_NO = #{memberPtNo}

mapper.select:
SELECT
COUNT(*)
FROM T_MEMBER_PT_MST mpm
    INNER JOIN T_CONT_MST cm ON cm.CONT_NO = mpm.CONT_NO

                AND (STR_TO_DATE(#{baseDt}, '%Y%m%d%H%i%S') BETWEEN cm.START_DT AND cm.END_DT)


                AND cm.CONT_STS_CD = #{contStsCd}

    LEFT OUTER JOIN (SELECT CONT_NO, SUM(BAL_PT) BAL_PT
                       FROM T_PT_MST
                       WHERE EXP_DT > CURRENT_TIMESTAMP(6) AND BAL_PT > 0

                            AND MEMBER_PT_NO = #{memberPtNo}


                            AND MEMBER_NO = #{memberNo}


                            AND CONT_NO = #{contNo}

                        GROUP BY CONT_NO
                       )  AS pm
                       ON pm.CONT_NO = mpm.CONT_NO
WHERE 1 = 1 AND (CASE WHEN pm.BAL_PT IS NULL THEN 0 ELSE pm.BAL_PT END) > 0

    AND mpm.MEMBER_NO = #{memberNo}


    AND mpm.CONT_NO = #{contNo}


    AND mpm.CONT_NO IN

        #{contNo}



    AND mpm.ORG_NO = #{orgNo}


    AND (CASE WHEN pm.BAL_PT IS NULL THEN 0 ELSE pm.BAL_PT END) > #{baseBalPt}

SELECT T.ROW_NUM AS ROW_NUM ,T.* FROM ( SELECT ROW_NUMBER() OVER(ORDER BY mpm.ORG_NO, mpm.MEMBER_NO) ROW_NUM ,mpm.MEMBER_PT_NO ,mpm.MEMBER_NO ,mpm.CONT_NO ,cm.CONT_NM ,mpm.ORG_NO ,(CASE WHEN pm.BAL_PT IS NULL THEN 0 ELSE pm.BAL_PT END) AS BAL_PT ,mpm.ISU_PT ,mpm.ISU_CANCEL_PT ,mpm.USE_PT ,mpm.USE_CANCEL_PT ,mpm.EXP_PT ,mpm.REG_USER_ID ,mpm.REG_DT ,mpm.LAST_MOD_USER_ID ,mpm.LAST_MOD_DT FROM T_MEMBER_PT_MST mpm INNER JOIN T_CONT_MST cm ON cm.CONT_NO = mpm.CONT_NO
AND (#{baseDt, jdbcType=TIMESTAMP} BETWEEN cm.START_DT AND cm.END_DT)
AND cm.CONT_STS_CD = #{contStsCd}
LEFT OUTER JOIN (SELECT CONT_NO, SUM(BAL_PT) BAL_PT FROM T_PT_MST WHERE EXP_DT > CURRENT_TIMESTAMP(6) AND BAL_PT > 0
AND MEMBER_PT_NO = #{memberPtNo}
AND MEMBER_NO = #{memberNo}
AND CONT_NO = #{contNo}
GROUP BY CONT_NO ) AS pm ON pm.CONT_NO = mpm.CONT_NO WHERE 1 = 1 AND (CASE WHEN pm.BAL_PT IS NULL THEN 0 ELSE pm.BAL_PT END) > 0
AND mpm.MEMBER_NO = #{memberNo}
AND mpm.CONT_NO = #{contNo}
AND mpm.CONT_NO IN
#{contNo}
AND mpm.ORG_NO = #{orgNo}
AND (CASE WHEN pm.BAL_PT IS NULL THEN 0 ELSE pm.BAL_PT END) > #{baseBalPt}
ORDER BY mpm.ORG_NO, mpm.MEMBER_NO ) T
WHERE T.ROW_NUM BETWEEN #{startIndex} AND #{endIndex}
